static Student mapRow(ResultSet rs) throws SQLException {
  return new Student(rs.getInt("id"), rs.getString("name"), rs.getBigDecimal("grade_avg"));
}
static Optional<Student> findById(Connection conn, int id) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM students WHERE id=?")) {
    ps.setInt(1, id);
    try (ResultSet rs = ps.executeQuery()) { if (rs.next()) return Optional.of(mapRow(rs)); return Optional.empty(); }
  }
}

