try (ResultSet rs = s.executeQuery("SELECT * FROM students")) {
  ResultSetMetaData meta = rs.getMetaData();
  int cols = meta.getColumnCount();
  System.out.println(cols);
  for (int i = 1; i <= cols; i++) System.out.println(meta.getColumnName(i));
}

static void printAnyResultSet(ResultSet rs) throws SQLException {
  ResultSetMetaData meta = rs.getMetaData();
  int cols = meta.getColumnCount();
  while (rs.next()) {
    StringBuilder sb = new StringBuilder();
    for (int i = 1; i <= cols; i++) sb.append(meta.getColumnName(i)).append("=").append(rs.getObject(i)).append(" ");
    System.out.println(sb);
  }
}

static List<Map<String,Object>> resultSetToMaps(ResultSet rs) throws SQLException {
  ResultSetMetaData meta = rs.getMetaData();
  int cols = meta.getColumnCount();
  List<Map<String,Object>> result = new ArrayList<>();
  while (rs.next()) {
    Map<String,Object> row = new LinkedHashMap<>();
    for (int i = 1; i <= cols; i++) row.put(meta.getColumnName(i), rs.getObject(i));
    result.add(row);
  }
  return result;
}

static Student mapRowStrict(ResultSet rs) throws SQLException {
  BigDecimal avg = rs.getBigDecimal("grade_avg");
  if (avg == null) throw new IllegalStateException("grade_avg jest NULL");
  return new Student(rs.getInt("id"), rs.getString("name"), avg);
}
static Student mapRowLenient(ResultSet rs) throws SQLException {
  BigDecimal avg = rs.getBigDecimal("grade_avg");
  return new Student(rs.getInt("id"), rs.getString("name"), avg != null ? avg : BigDecimal.ZERO);
}

